package com.banglish.data.generator;

import com.banglish.data.generator.data.BangladeshiNames;

import java.util.Objects;
import java.util.Random;

/**
 * Generator for synthetic Bangladeshi names.
 * <p>
 * Disclaimer: All names generated by this library are synthetic test data
 * and must not be treated as representations of real-person identity records.
 */
public class NameGenerator {

    private final Random random;

    /**
     * Constructs a NameGenerator with a specific random number generator.
     *
     * @param random random source
     */
    public NameGenerator(Random random) {
        this.random = Objects.requireNonNull(random, "Random generator must not be null");
    }

    /**
     * Generates a random Bangladeshi first name (either male or female).
     *
     * @return a first name
     */
    public String getFirstName() {
        boolean isMale;
        int maleIdx, femaleIdx;
        synchronized (random) {
            isMale = random.nextBoolean();
            maleIdx = random.nextInt(BangladeshiNames.MALE_FIRST_NAMES.size());
            femaleIdx = random.nextInt(BangladeshiNames.FEMALE_FIRST_NAMES.size());
        }
        return isMale
                ? BangladeshiNames.MALE_FIRST_NAMES.get(maleIdx)
                : BangladeshiNames.FEMALE_FIRST_NAMES.get(femaleIdx);
    }

    /**
     * Generates a random Bangladeshi family surname / last name.
     *
     * @return a last name
     */
    public String getLastName() {
        int index;
        synchronized (random) {
            index = random.nextInt(BangladeshiNames.LAST_NAMES.size());
        }
        return BangladeshiNames.LAST_NAMES.get(index);
    }

    /**
     * Generates a full male Bangladeshi name (first name and last name).
     *
     * @return a full male name
     */
    public String getMaleName() {
        int firstIdx, lastIdx;
        synchronized (random) {
            firstIdx = random.nextInt(BangladeshiNames.MALE_FIRST_NAMES.size());
            lastIdx = random.nextInt(BangladeshiNames.LAST_NAMES.size());
        }
        return BangladeshiNames.MALE_FIRST_NAMES.get(firstIdx) + " " + BangladeshiNames.LAST_NAMES.get(lastIdx);
    }

    /**
     * Generates a full female Bangladeshi name (first name and last name).
     *
     * @return a full female name
     */
    public String getFemaleName() {
        int firstIdx, lastIdx;
        synchronized (random) {
            firstIdx = random.nextInt(BangladeshiNames.FEMALE_FIRST_NAMES.size());
            lastIdx = random.nextInt(BangladeshiNames.LAST_NAMES.size());
        }
        return BangladeshiNames.FEMALE_FIRST_NAMES.get(firstIdx) + " " + BangladeshiNames.LAST_NAMES.get(lastIdx);
    }

    /**
     * Generates a full Bangladeshi name (either male or female).
     *
     * @return a full name
     */
    public String getName() {
        boolean isMale;
        synchronized (random) {
            isMale = random.nextBoolean();
        }
        return isMale ? getMaleName() : getFemaleName();
    }
}
